// Standalone design prototype. Fictional records only; no network or persistent storage.
const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const people=[
 {name:'Meera Rao',born:'12 April 1948',place:'Mangaluru',work:'Teacher',initials:'MR',story:'Meera grew up in Mangaluru, in a house where cousins and neighbours were always coming and going. She became a teacher and spent much of her working life in Bengaluru.\n\nShe remembers her students by name. At home, she kept notebooks of recipes and taught the grandchildren to cook by letting them help, even when it took longer.',hobbies:'Cooking, reading, gardening'},
 {name:'Kavya Rao',born:'21 June 1975',place:'Bengaluru',work:'Architect',initials:'KR',story:'Kavya always liked to draw the houses she visited. Years later, architecture became her profession. Her favourite projects are the ones that make everyday life a little easier.',hobbies:'Drawing, walking'},
 {name:'Nikhil Rao',born:'8 November 1978',place:'Bengaluru',work:'Musician',initials:'NR',story:'Music was part of everyday life for Nikhil. He remembers learning songs with his mother and later finding friends who liked playing them as much as he did.',hobbies:'Music, carpentry'},
 {name:'Tara Rao',born:'17 February 2003',place:'Pune',work:'Student',initials:'TR',story:'Tara is collecting family photographs and asking her grandmother about the people in them.',hobbies:'Photography'}
];
let selected=0,scenario='returning',tab='story',picked=false,zoom=1,modalType='',dirty=false,lastFocus=null;
const viewer=()=>scenario==='viewer';
const page=()=>['tree','people','places','access'].includes(location.hash.slice(1))?location.hash.slice(1):'tree';
const avatar=p=>`<span class="avatar">${esc(p.initials)}</span>`;
const primary=(label,action)=>`<button class="primary" data-action="${action}">${label}</button>`;
function heading(title,desc,action=''){return `<header class="page-head"><div><h1>${title}</h1><p>${desc}</p></div>${action}</header>`}
function notify(text){$('#notice').textContent=text;$('#notice').classList.add('show');clearTimeout(window.noticeTimer);window.noticeTimer=setTimeout(()=>$('#notice').classList.remove('show'),4500)}
function render(){
 $('#role-name').textContent=viewer()?'Viewer':'Owner';
 $('.sidebar').hidden=scenario==='signedout';
 $('#shell').style.display=scenario==='signedout'?'block':'';
 document.querySelectorAll('[data-page]').forEach(a=>{if(a.dataset.page===page())a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});
 if(scenario==='signedout'){$('#main').innerHTML=`<section class="signedout"><a class="brand" href="#tree">Viraasat</a><div class="empty"><p class="eyebrow">A PRIVATE FAMILY ARCHIVE</p><h1>A place for your family’s stories.</h1><p>Keep the people, memories and places that matter to your family together.</p>${primary('Continue with Google','signin')}<p class="minor">This beta is open to approved testers.<br>Contact the project owner if you need access.</p></div></section>`;return}
 if(scenario==='first'){$('#main').innerHTML=heading('Your family tree','Start with someone you know.')+`<section class="empty"><span class="avatar">V</span><h2>Who would you like to start with?</h2><p>A name is enough for now. You can add stories, photographs and relatives whenever you’re ready.</p>${primary('Start my family','first-add')}<button class="quiet" data-action="sample">Or explore a fictional sample</button></section>`;return}
 $('#main').innerHTML=({tree:tree,people:profiles,places:places,access:access})[page()]();
}
function tree(){return heading('Family tree','The Rao family · '+people.length+' people',viewer()?'<span class="badge">View only</span>':primary('+ Add person','add'))+`<section class="tree-board" aria-label="Family tree"><div class="toolbar"><label><span class="sr-label" hidden>Find a person</span><input type="search" id="tree-search" aria-label="Find a person in the tree" placeholder="Find a person…"></label><span>Starts with Meera Rao</span><button data-action="view">View options</button></div><div class="canvas"><div class="graph" style="transform:scale(${zoom})"><svg viewBox="0 0 850 480" aria-hidden="true"><g fill="none" stroke="#a4b5a3" stroke-width="1.5"><path d="M425 118 V168 H270 V210 M425 168 H580 V210 M270 290 V380"/></g><g fill="#6b7b6a" font-family="Arial" font-size="11"><text x="438" y="159">Children</text></g></svg>${people.slice(0,4).map((p,i)=>`<button class="person-node n${i} ${picked&&selected===i?'selected':''}" data-person="${i}" aria-label="Select ${esc(p.name)}">${avatar(p)}<span><b>${esc(p.name)}</b><small>${esc(p.born.slice(-4))} · ${esc(p.work)}</small></span></button>`).join('')}</div></div>${picked?`<aside class="selection" aria-label="Selected person"><button class="icon dismiss" data-action="dismiss" aria-label="Close selected person">×</button>${avatar(people[selected])}<h2>${esc(people[selected].name)}</h2><p class="muted">Born ${esc(people[selected].born)}<br>${esc(people[selected].place)}</p><a href="#people">Read their story →</a></aside>`:''}<div class="canvas-foot"><span>Select a person to see their story.</span><div class="zoom"><button data-action="out" aria-label="Zoom out">−</button><button data-action="in" aria-label="Zoom in">+</button><button data-action="fit">Fit</button></div></div></section><p class="hint">${viewer()?'You can explore this family. Only owners and editors can make changes.':'Connections show recorded relationships. Select a person to explore further.'}</p>`}
function profiles(){let p=people[selected];return heading('People','Stories and details, one person at a time.',viewer()?'':primary('+ Add person','add'))+`<label class="mobile-person">Person<select id="mobile-person">${people.map((x,i)=>`<option value="${i}" ${i===selected?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><div class="directory-layout"><aside class="directory" aria-label="Family directory"><label>Find a person<input id="people-search" type="search" placeholder="Name or birthplace"></label>${people.map((x,i)=>`<button class="${selected===i?'active':''}" data-person="${i}" data-search="${esc((x.name+' '+x.place).toLowerCase())}" aria-pressed="${selected===i}">${avatar(x)}<span><b>${esc(x.name)}</b><small>${esc(x.work)}</small></span></button>`).join('')}</aside><article class="profile"><header class="profile-head">${avatar(p)}<div><h2>${esc(p.name)}</h2><p>Born ${esc(p.born)} · ${esc(p.place)}</p></div>${viewer()?'<span class="badge">View only</span>':'<button data-action="edit">Edit profile</button>'}</header><div class="tabs" role="tablist" aria-label="Profile sections"><button role="tab" aria-selected="${tab==='story'}" data-tab="story">Story</button><button role="tab" aria-selected="${tab==='photos'}" data-tab="photos">Photos</button></div>${tab==='story'?`<div role="tabpanel" aria-label="Story"><p class="prose">${esc(p.story)}</p><dl class="facts"><div><dt>Birthplace</dt><dd>${esc(p.place)}</dd></div><div><dt>Work</dt><dd>${esc(p.work)}</dd></div><div><dt>Enjoys</dt><dd>${esc(p.hobbies)}</dd></div></dl>${!viewer()?'<details><summary>Health notes · owners and editors only</summary><p>No health notes in this fictional example. Production will preserve the existing server-side permissions.</p></details>':''}<details><summary>Family conversation</summary><p>No messages yet. A family conversation belongs beside the person’s story, not in the global navigation.</p><label>Add a memory<textarea id="memory" rows="3" placeholder="What do you remember?"></textarea></label><button data-action="memory">Post memory</button></details><details><summary>Change history</summary><p>This is a fictional example. In the app, saved revisions and their authors would appear here.</p></details></div>`:`<div role="tabpanel" aria-label="Photos"><div class="photos"><div class="photo">Family album<small>Photo placeholder · no real upload</small></div><div class="photo">An afternoon together<small>Photo placeholder · no real upload</small></div></div>${!viewer()?'<p class="hint"><button data-action="upload">Add a photo</button></p>':''}</div>`}</article></div>`}
function places(){let p=people[selected];return heading('Places & time','The places and moments recorded by your family.',viewer()?'':primary('Add a place or event','place'))+`<div class="places-layout"><aside class="places-nav"><label>Showing records for<select id="place-person">${people.map((x,i)=>`<option value="${i}" ${i===selected?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><p>Only recorded events appear here. Missing dates and locations remain unknown.</p></aside><article class="timeline"><h2>${esc(p.name)}’s recorded places</h2><div class="event"><time>${esc(p.born)}</time><h3>${esc(p.place)}</h3><p>Born in ${esc(p.place)}.</p><small>From their profile</small></div>${selected===0?`<div class="event"><time>Date not recorded</time><h3>Bengaluru</h3><p>Worked as a teacher. The family has not recorded when she moved.</p><small>Fictional example of a family-recorded place</small></div>`:''}<details style="margin-top:28px"><summary>Map options</summary><p>Only places with recorded coordinates can be plotted. This mockup does not add geocoding or infer a route.</p><button data-action="map">Preview map state</button></details><details><summary>Historical context</summary><p>No historical events have been linked to this person yet.</p>${viewer()?'':'<button data-action="context">Link an event</button>'}</details></article></div>`}
function access(){return `<div class="access">${heading('Family access','People who can open the Rao family archive.',viewer()?'<span class="badge">View only</span>':primary('Invite someone','invite'))}<section class="access-card" aria-label="Members"><div class="member-row"><span class="avatar">NP</span><div><b>Nihal Pai</b><small>You</small></div><span>${viewer()?'Viewer':'Owner'}</span></div><div class="member-row"><span class="avatar">AT</span><div><b>Approved tester</b><small>Fictional member</small></div>${viewer()?'<span>Owner</span>':'<button data-action="role">Viewer ⌄</button>'}</div></section><p class="access-info">Viewers can read shared stories and photos. Editors can also change records and read health notes. Only owners manage access.</p><details><summary>Invitations <span class="muted">· none pending</span></summary><p>An invitation appears here until it is accepted, expires or is revoked.</p></details><details><summary>Family settings & history</summary><p>Account sign-out and your personal invitation code are in the account menu.</p>${viewer()?'':'<button data-action="ownership">Transfer ownership</button>'}<button class="quiet" data-action="history">View family history</button></details></div>`}
function openModal(type){modalType=type;dirty=false;lastFocus=document.activeElement;let p=people[selected];let titles={add:['ADD TO THE RAO FAMILY','Who are we adding?'], 'first-add':['START YOUR FAMILY','Who would you like to remember?'], edit:['PERSON PROFILE','Edit '+p.name], invite:['FAMILY ACCESS','Invite someone'],view:['FAMILY TREE','View options'],code:['YOUR ACCOUNT','Your invitation code'],place:['PLACES & TIME','Add a recorded place'],role:['FAMILY ACCESS','Change access'],ownership:['OWNER SETTINGS','Transfer ownership'],history:['FAMILY HISTORY','Changes to this family'],map:['PLACES & TIME','Map view'],context:['HISTORICAL CONTEXT','Link a recorded event'],upload:['PHOTOS','Add a photo']};let t=titles[type];$('#dialog-kicker').textContent=t[0];$('#dialog-title').textContent=t[1];$('#modal-note').textContent='Prototype only · no real data is saved';$('#modal-submit').hidden=false;
 let bodies={
 add:`<p>Start with a name and a connection. Their story can grow over time.</p><label>Their name<input name="name" required placeholder="Full name"></label><label>Connection to someone in this family<select name="relationship"><option>No connection yet</option><option>Child of Meera Rao</option><option>Parent of Meera Rao</option><option>Partner of Meera Rao</option></select></label><details><summary>Add more about them (optional)</summary><label>What do you remember?<textarea name="story" rows="4" placeholder="A habit, a favourite place, a story they told…"></textarea></label><p>Further guided prompts could be offered here without making everyone complete a fixed sequence.</p></details>`,
 edit:`<label>Full name<input name="name" value="${esc(p.name)}" required></label><label>Their story<textarea name="story" rows="6">${esc(p.story)}</textarea></label><details><summary>Dates, birthplace and other details</summary><label>Birthplace<input name="place" value="${esc(p.place)}"></label><label>Work<input name="work" value="${esc(p.work)}"></label></details>`,
 invite:`<p>Ask an approved tester to sign in and copy their invitation code from their account menu.</p><label>Their invitation code<input name="code" required placeholder="Paste the code they shared"></label><label>Access<select name="role"><option>Viewer</option><option>Editor</option></select></label><p id="role-help">Viewer can read stories and photos. Health notes remain private.</p><p>They will need to accept the invitation. It expires after 7 days.</p>`,
 view:`<label>Start with<select name="root">${people.map(x=>`<option>${esc(x.name)}</option>`).join('')}</select></label><label>Show<select><option>Children and grandchildren</option><option>Parents and grandparents</option></select></label><details><summary>Advanced view options</summary><label>Generations<input type="number" min="1" max="10" value="2"></label><label><input type="checkbox" checked style="width:auto;display:inline;min-height:0;margin-right:9px"> Include partners</label></details>`,
 code:`<p>Share this with a circle owner so they can invite you. This code identifies your account; it does not grant access by itself.</p><label>Example invitation code<input readonly value="DEMO-ACCOUNT-CODE"></label>`,
 place:`<label>Person<select>${people.map((x,i)=>`<option ${selected===i?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><label>Place name<input required placeholder="Town or city"></label><label>Date, if known<input type="date"></label><label>What happened here?<textarea rows="3"></textarea></label><details><summary>Map coordinates (optional)</summary><label>Latitude<input type="number" step="any"></label><label>Longitude<input type="number" step="any"></label></details>`,
 role:`<p>Change access for the fictional member “Approved tester.”</p><label>Role<select name="role"><option>Viewer</option><option>Editor</option></select></label><p id="role-help">Viewer can read stories and photos. Health notes remain private.</p>`,
 ownership:`<p>In production this would require selecting an existing member, explaining the transfer, and confirming the recipient. This prototype does not transfer ownership.</p><p>Keeping it separate from everyday invitations reduces accidental changes.</p>`,
 history:`<p>Saved changes would appear here with their author, date and affected person. Raw audit action codes would be translated into clear descriptions.</p>`,
 map:`<div class="map-note"><b>No coordinates recorded in this example.</b><p>Places remain readable in the timeline. A production map would show recorded locations only, without inventing a travel route.</p></div>`,
 context:`<p>The existing event picker would be scoped to ${esc(p.name)}. Linking an event is optional; empty world-event rows no longer appear throughout the timeline.</p>`,
 upload:`<p>The current private upload endpoint remains in use. The intended flow accepts JPEG/PNG, shows upload progress, and keeps any error beside the picker.</p><label>Choose a photo<input type="file" accept="image/jpeg,image/png"></label><p>No file is uploaded by this mockup.</p>`};
 bodies['first-add']=`<label>Family name<input name="family" value="My family" required></label><label>Their name<input name="name" required placeholder="Full name"></label><p>You can connect relatives and add details later.</p>`;
 $('#dialog-body').innerHTML=bodies[type];$('#modal-submit').textContent=({add:'Add person','first-add':'Create family',edit:'Save changes',invite:'Send invitation',view:'Apply view',code:'Copy example code',place:'Save place',role:'Save access',upload:'Preview upload result'})[type]||'Done';$('#dialog').showModal();$('#dialog-body input, #dialog-body select, #dialog-body textarea')?.focus();}
function closeModal(){if(dirty&&!confirm('Discard these unsaved changes?'))return;$('#dialog').close();dirty=false;lastFocus?.focus()}
$('#close').onclick=closeModal;$('#dialog').addEventListener('cancel',e=>{e.preventDefault();closeModal()});$('#modal-form').addEventListener('input',()=>{dirty=true});$('#modal-form').addEventListener('change',e=>{if(e.target.name==='role')$('#role-help').textContent=e.target.value==='Editor'?'Editor can change family records and read health notes.':'Viewer can read stories and photos. Health notes remain private.'});
$('#modal-form').onsubmit=e=>{e.preventDefault();const d=new FormData(e.target);if(modalType==='edit'){Object.assign(people[selected],{name:d.get('name'),story:d.get('story'),place:d.get('place'),work:d.get('work')});notify('Changes saved in this mockup.')}else if(['add','first-add'].includes(modalType)){people.push({name:d.get('name'),born:'Date not recorded',place:'Not recorded',work:'',initials:d.get('name').split(' ').map(x=>x[0]).slice(0,2).join(''),story:d.get('story')||'No story recorded yet.',hobbies:''});selected=people.length-1;scenario='returning';$('#scenario').value='returning';location.hash='people';notify('Person added to the mockup. No live records changed.')}else if(modalType==='code'){navigator.clipboard?.writeText('DEMO-ACCOUNT-CODE').then(()=>notify('Example code copied.')).catch(()=>notify('Select and copy the example code manually.'));}else if(modalType==='invite')notify('Invitation preview complete. No invitation was sent.');else if(modalType==='view')notify('View options previewed. This mockup uses a fixed sample tree.');else notify('Preview complete. No live records changed.');dirty=false;$('#dialog').close();render();lastFocus?.focus()};
$('#account').onclick=()=>{$('#account-menu').hidden=!$('#account-menu').hidden};
$('#scenario').onchange=e=>{scenario=e.target.value;picked=false;$('#account-menu').hidden=true;render()};
document.addEventListener('click',e=>{let person=e.target.closest('[data-person]');if(person){selected=Number(person.dataset.person);picked=true;render();return}let t=e.target.closest('[data-tab]');if(t){tab=t.dataset.tab;render();return}let a=e.target.closest('[data-action]');if(!a)return;let action=a.dataset.action;
 if(action==='dismiss'){picked=false;render()}else if(['in','out','fit'].includes(action)){zoom=action==='fit'?1:Math.min(1.5,Math.max(.65,zoom+(action==='in'?.1:-.1)));$('.graph').style.transform=`scale(${zoom})`}else if(action==='sample'){scenario='returning';$('#scenario').value=scenario;location.hash='tree';render()}else if(action==='signout'){scenario='signedout';$('#scenario').value=scenario;$('#account-menu').hidden=true;render()}else if(action==='signin')notify('Prototype only. Production uses the existing approved Google sign-in.');else if(action==='memory'){let value=$('#memory').value;if(value.trim()){notify('Memory previewed. No message sent.');$('#memory').value=''}else $('#memory').focus()}else openModal(action);
});
document.addEventListener('input',e=>{if(e.target.id==='people-search'){let q=e.target.value.toLowerCase();document.querySelectorAll('[data-search]').forEach(x=>x.hidden=!x.dataset.search.includes(q))}if(e.target.id==='tree-search'){let q=e.target.value.toLowerCase();document.querySelectorAll('.person-node').forEach((x,i)=>{x.style.opacity=people[i].name.toLowerCase().includes(q)?1:.25})}});
document.addEventListener('change',e=>{if(['place-person','mobile-person'].includes(e.target.id)){selected=Number(e.target.value);render()}});
window.addEventListener('hashchange',()=>{picked=false;$('#account-menu').hidden=true;render();$('#main').focus({preventScroll:true});window.scrollTo(0,0)});render();
